content.css:
:root {
  --atlyn-background: #ffffff;
  --atlyn-foreground: #242424;
  --atlyn-muted: #5f6368;
  --atlyn-accent: #2764c4;
  --atlyn-selected: #2764c4;
  --atlyn-border: #d9dce1;
  --atlyn-warning: #8a4b00;
  --atlyn-error: #b42318;
  --atlyn-node-fill: #ffffff;
  --atlyn-label: #242424;
  --atlyn-subtitle: #5f6368;
  --atlyn-edge: #d9dce1;
  --atlyn-font-family: Arial, sans-serif;
  --atlyn-label-size: 12px;
  --atlyn-subtitle-size: 10px;
  --atlyn-edge-width: 1.5;
}
/*
 * The visually-hidden idiom: present to a screen reader, absent from layout.
 */
/*
 * No min-height. The host tile is the authority on how much room there is, and
 * it clips at its own edge with no scrollbar: a floor of 96px inside an 80px
 * tile does not make the visual 96px tall, it makes 16px of it disappear.
 */
.atlyn-root {
  background: var(--atlyn-background);
  color: var(--atlyn-foreground);
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  font-family: var(--atlyn-font-family);
  font-size: 13px;
  height: 100%;
  overflow: hidden;
  position: relative;
  width: 100%;
}
.atlyn-root *,
.atlyn-root *::before,
.atlyn-root *::after {
  box-sizing: inherit;
}
.atlyn-toolbar {
  align-items: center;
  border-bottom: 1px solid var(--atlyn-border);
  display: flex;
  flex: 0 0 auto;
  flex-wrap: wrap;
  gap: 6px;
  min-height: 38px;
  padding: 6px 8px;
}
.atlyn-toolbar label {
  color: var(--atlyn-muted);
  font-weight: 600;
}
.atlyn-search {
  background: var(--atlyn-background);
  border: 1px solid var(--atlyn-border);
  border-radius: 3px;
  color: inherit;
  flex: 1 1 120px;
  min-width: 80px;
  padding: 5px 7px;
}
.atlyn-button {
  background: var(--atlyn-background);
  border: 1px solid var(--atlyn-border);
  border-radius: 3px;
  color: inherit;
  cursor: pointer;
  min-height: 27px;
  padding: 4px 8px;
}
.atlyn-button:hover,
.atlyn-button:focus-visible,
.atlyn-node:focus-visible,
.atlyn-semantic-item:focus-visible {
  outline: 2px solid var(--atlyn-accent);
  outline-offset: 1px;
}
.atlyn-button:disabled {
  cursor: default;
  opacity: 0.5;
}
.atlyn-status {
  color: var(--atlyn-muted);
  flex: 0 0 auto;
  min-height: 24px;
  padding: 4px 8px;
}
/*
 * The strips above the canvas keep their natural height so a data quality
 * message is never sliced in half when the canvas is under vertical pressure;
 * only .atlyn-canvas-wrap absorbs the remaining space.
 */
.atlyn-diagnostics {
  border-bottom: 1px solid var(--atlyn-border);
  flex: 0 0 auto;
  max-height: 86px;
  overflow: auto;
  padding: 4px 8px;
}
.atlyn-diagnostic {
  margin: 2px 0;
}
.atlyn-diagnostic[data-severity="error"] {
  color: var(--atlyn-error);
}
.atlyn-diagnostic[data-severity="warning"] {
  color: var(--atlyn-warning);
}
.atlyn-breadcrumb {
  color: var(--atlyn-muted);
  flex: 0 0 auto;
  min-height: 25px;
  overflow: hidden;
  padding: 4px 8px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/*
 * The canvas keeps no floor of its own on purpose: it is the item that shrinks,
 * and a floor here would only move the overflow onto the strips above it. What
 * keeps it alive is that density drops chrome the tile cannot afford, and the
 * probe's collapsed-region rule fails the build if that ever stops being true.
 */
.atlyn-canvas-wrap {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  position: relative;
  touch-action: pan-y;
}
.atlyn-graph {
  display: block;
  min-height: 170px;
  width: 100%;
}
.atlyn-edge {
  stroke: var(--atlyn-edge);
  stroke-width: var(--atlyn-edge-width);
}
.atlyn-node-card {
  fill: var(--atlyn-node-fill);
  stroke: var(--atlyn-accent);
  stroke-width: var(--atlyn-edge-width);
}
.atlyn-node-card[data-selected="true"] {
  stroke: var(--atlyn-selected);
  stroke-width: max(2px, calc(var(--atlyn-edge-width) + 1px));
}
.atlyn-node-card[data-search-match="true"] {
  fill: #fff4c2;
}
.atlyn-node-label {
  fill: var(--atlyn-label);
  font-size: var(--atlyn-label-size);
  pointer-events: none;
}
.atlyn-node-subtitle {
  fill: var(--atlyn-subtitle);
  font-size: var(--atlyn-subtitle-size);
  pointer-events: none;
}
.atlyn-semantic-tree {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  margin: 0;
  max-height: 1px;
  min-height: 0;
  overflow: hidden;
  padding: 0;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}
/*
 * When the tree takes focus it rejoins the flow as a pane. It does not shrink:
 * flex: 0 1 auto here would let the canvas's own enormous content basis pull
 * shrinkage onto the tree at ordinary tile sizes, and the tree would render
 * shorter than the rows it is showing on a 1366x768 report page. What keeps the
 * pane and the canvas from fighting at small tiles is density, which drops the
 * toolbar while the tree holds focus, and the floor below.
 */
.atlyn-semantic-tree:focus-within {
  border-top: 1px solid var(--atlyn-border);
  clip: auto;
  clip-path: none;
  flex: 0 0 auto;
  height: auto;
  margin: 0;
  max-height: 38%;
  /*
   * One whole row, even when 38% of the tile is less than that. A pane shorter
   * than the row it is showing leaves the keyboard user focused on something
   * the tile has cut in half, which is the defect this pane exists to avoid.
   */
  min-height: 42px;
  overflow: auto;
  padding: 4px 8px;
  position: relative;
  white-space: normal;
  width: auto;
}
/*
 * Every row reserves the toggle column so leaves line up under their parents;
 * without the reservation a childless node sits further left than the node it
 * belongs to. The toggle is pulled back into that reserved space.
 */
.atlyn-semantic-item {
  align-items: center;
  display: flex;
  gap: 4px;
  min-height: 25px;
  padding-inline-start: calc((var(--atlyn-level) - 1) * 17px + 32px);
}
.atlyn-semantic-item[aria-selected="true"] {
  background: #e7efff;
}
.atlyn-semantic-label {
  background: transparent;
  color: inherit;
  display: block;
  overflow: hidden;
  padding: 3px;
  text-align: start;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.atlyn-semantic-toggle {
  background: transparent;
  border: 0;
  color: inherit;
  cursor: pointer;
  margin-inline-start: -32px;
  min-height: 32px;
  min-width: 32px;
}
.atlyn-semantic-item {
  cursor: pointer;
  touch-action: manipulation;
}
/*
 * Density. src/visual.ts publishes the tile the host reported as
 * data-density, and each step below drops the chrome that no longer fits
 * rather than letting the flex column push it - and everything after it - past
 * the clipped edge of the tile.
 *
 * Strips that carry information a screen reader needs are hidden the
 * accessible way rather than removed: the status strip is a live region, and
 * silencing it would trade a layout defect for an accessibility one.
 */
.atlyn-root[data-density="compact"] .atlyn-breadcrumb,
.atlyn-root[data-density="compact"] .atlyn-toolbar label,
.atlyn-root[data-density="compact"] .atlyn-button,
.atlyn-root[data-density="minimal"] .atlyn-breadcrumb,
.atlyn-root[data-density="minimal"] .atlyn-toolbar label,
.atlyn-root[data-density="minimal"] .atlyn-button {
  display: none;
}
.atlyn-root[data-density="compact"] .atlyn-search,
.atlyn-root[data-density="minimal"] .atlyn-search {
  flex: 1 1 auto;
  min-width: 0;
}
.atlyn-root[data-density="minimal"] .atlyn-status,
.atlyn-root[data-density="minimal"] .atlyn-diagnostics {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  margin: 0;
  max-height: 1px;
  min-height: 0;
  overflow: hidden;
  padding: 0;
  position: absolute;
  white-space: nowrap;
  width: 1px;
  border: 0;
  flex: 0 0 auto;
}
/*
 * At minimal density the search box is the only control left, so it stops
 * insisting on a width the tile may not have.
 */
.atlyn-root[data-density="minimal"] .atlyn-toolbar {
  min-height: 0;
}
/*
 * An 80x80 tile cannot show a toolbar and a tree pane at once. While the tree
 * holds focus the tree wins, because that is what the user is reading.
 */
.atlyn-root[data-density="minimal"][data-tree-focused="true"] .atlyn-toolbar {
  display: none;
}
.atlyn-empty {
  color: var(--atlyn-muted);
  padding: 20px 8px;
  text-align: center;
}
.atlyn-root[data-high-contrast="true"] {
  --atlyn-warning: var(--atlyn-foreground);
  --atlyn-error: var(--atlyn-foreground);
}
.atlyn-root[data-high-contrast="true"] .atlyn-node-card[data-search-match="true"] {
  fill: var(--atlyn-background);
  stroke: var(--atlyn-foreground);
}
.atlyn-root[data-high-contrast="true"] .atlyn-semantic-item[aria-selected="true"] {
  background: var(--atlyn-background);
  outline: 1px solid var(--atlyn-foreground);
}
.atlyn-root[data-high-contrast="true"] .atlyn-node-card {
  stroke: var(--atlyn-foreground);
}
.atlyn-root[data-interactions-disabled="true"] .atlyn-button,
.atlyn-root[data-interactions-disabled="true"] .atlyn-semantic-item,
.atlyn-root[data-interactions-disabled="true"] .atlyn-semantic-toggle {
  cursor: default;
}
.atlyn-root[data-reduced-motion="true"] * {
  scroll-behavior: auto !important;
  transition: none !important;
}
@media (prefers-reduced-motion: reduce) {
  .atlyn-root * {
    scroll-behavior: auto !important;
    transition: none !important;
  }
}
/*
 * Scoped to comfortable density. Below that the toolbar has already lost its
 * label, and giving the search a full row of its own would spend height the
 * tile does not have.
 */
@media (max-width: 480px) {
  .atlyn-root[data-density="comfortable"] .atlyn-toolbar {
    align-items: stretch;
  }
  .atlyn-root[data-density="comfortable"] .atlyn-toolbar label {
    flex-basis: 100%;
  }
  .atlyn-root[data-density="comfortable"] .atlyn-search {
    flex-basis: 100%;
  }
}
